(() => {
  'use strict';

  // ============================================================
  // 1) KARAKTER — gambar di bawah sudah tertanam di HTML.
  //    Tidak perlu server asset tambahan.
  // ============================================================
  const CHARACTERS = [
    {
      name: 'Cabit',
      image: "data:image/png;base64,",
      chase: 1,
      speed: 115,
      hue: 210
    },
    {
      name: 'Ratono',
      image: "data:image/png;base64,",
      chase: 2,
      speed: 108,
      hue: 45
    },
    {
      name: 'Adjiemas',
      image: "data:image/png;base64,",
      chase: 0,
      speed: 102,
      hue: 200
    }
  ];

  // Crop orang dari kartu foto. Angka ini relatif terhadap gambar asli
  // 829x1288 yang kamu upload.
  const CROPS = [
    {x:255,y:225,w:574,h:825}, // Cabit
    {x:140,y:270,w:689,h:780}, // Ratono
    {x:305,y:220,w:524,h:830}  // Adjiemas
  ];

  const world = document.getElementById('pixel-world');
  const DPR = Math.min(window.devicePixelRatio || 1, 2);

  // ============================================================
  // 2) Ambil "tempat persembunyian" dari landing page secara otomatis.
  //    H1/H2/H3/p/button/card/project dll bisa jadi tempat mereka ngumpet.
  // ============================================================
  const SELECTORS = [
    'h1','h2','h3','h4','p','a','button',
    '.project','.projects .card','.card','.work','.portfolio-item',
    '[data-character-zone]'
  ].join(',');

  function getZones(){
    const els = [...document.querySelectorAll(SELECTORS)];
    const out = [];
    for(const el of els){
      if(el.closest('#pixel-world')) continue;
      const r = el.getBoundingClientRect();
      const cs = getComputedStyle(el);
      if(r.width < 35 || r.height < 12) continue;
      if(cs.display === 'none' || cs.visibility === 'hidden') continue;
      if(r.bottom < -100 || r.top > innerHeight + 100) continue;
      out.push({el, r});
    }
    return out;
  }

  function clamp(v,a,b){ return Math.max(a,Math.min(b,v)); }
  function lerp(a,b,t){ return a+(b-a)*t; }
  function dist(a,b){ return Math.hypot(a.x-b.x,a.y-b.y); }
  function smoothstep(t){ return t*t*(3-2*t); }

  // ============================================================
  // 3) Pixel sprite generator
  //    Foto diperkecil -> white background dibuang -> nearest-neighbor.
  // ============================================================
  function loadImage(src){
    return new Promise((resolve,reject)=>{
      const im = new Image();
      im.onload=()=>resolve(im);
      im.onerror=reject;
      im.src=src;
    });
  }

  async function makeSprite(ch, crop){
    const im = await loadImage(ch.image);
    const W=64, H=96;
    const c=document.createElement('canvas');
    c.width=W; c.height=H;
    const ctx=c.getContext('2d',{willReadFrequently:true});
    ctx.imageSmoothingEnabled=false;

    // Fit crop ke 64x96 tanpa mengubah rasio.
    const scale=Math.min(W/crop.w,H/crop.h);
    const dw=crop.w*scale, dh=crop.h*scale;
    ctx.drawImage(im,crop.x,crop.y,crop.w,crop.h,(W-dw)/2,(H-dh)/2,dw,dh);

    const img=ctx.getImageData(0,0,W,H);
    const d=img.data;

    // Hapus background yang mendekati putih.
    // Kulit/baju tetap karena tidak "putih netral".
    for(let i=0;i<d.length;i+=4){
      const r=d[i],g=d[i+1],b=d[i+2];
      const mx=Math.max(r,g,b), mn=Math.min(r,g,b);
      const nearWhite = r>214 && g>214 && b>214 && (mx-mn)<18;
      const paleBg = r>235 && g>235 && b>235;
      if(nearWhite || paleBg) d[i+3]=0;
    }
    ctx.putImageData(img,0,0);

    // Tambahkan outline tipis berbasis alpha untuk rasa sprite.
    const out=document.createElement('canvas');
    out.width=128; out.height=192;
    const o=out.getContext('2d');
    o.imageSmoothingEnabled=false;
    o.drawImage(c,0,0,128,192);
    return out;
  }

  class PixelChar{
    constructor(data,index,sprite){
      this.data=data;
      this.i=index;
      this.sprite=sprite;
      this.el=document.createElement('div');
      this.el.className='pixel-character';
      this.canvas=document.createElement('canvas');
      this.canvas.width=128; this.canvas.height=192;
      this.canvas.getContext('2d').imageSmoothingEnabled=false;
      this.canvas.getContext('2d').drawImage(sprite,0,0);
      this.bubble=document.createElement('div');
      this.bubble.className='bubble';
      this.bubble.textContent='...';
      this.el.append(this.canvas,this.bubble);

      // Dialog kecil ala game: muncul sebentar, diketik pelan, lalu hilang.
      this.speechTimer=1.2+Math.random()*2.0;
      this.speechHideTimer=0;
      this.speechIndex=0;
      this.speechText='';
      this.speaking=false;
      this.say('h-hi im <b>'+this.data.name+'</b>!', true);
      world.appendChild(this.el);

      this.x=innerWidth*(0.22+0.28*index);
      this.y=innerHeight*(0.55+0.08*index);
      this.vx=0; this.vy=0;
      this.tx=this.x; this.ty=this.y;
      this.scale=0.82;
      this.targetScale=.82;
      this.alpha=1;
      this.flip=1;
      this.state='roam';
      this.timer=1.5+Math.random()*2;
      this.zone=null;
      this.peekSide=1;
      this.phase=Math.random()*Math.PI*2;
      this.walk=0;
    }

    say(html, instant=false){
      this.speechText=html;
      this.speaking=true;
      this.speechIndex=0;
      this.speechTimer=2.6+Math.random()*2.8;
      this.speechHideTimer=0;
      this.el.classList.add('speaking');
      if(instant){
        this.bubble.innerHTML=html;
        return;
      }
      // Efek mengetik sederhana. Tag nama ditampilkan utuh setelah selesai.
      const plain=html.replace(/<[^>]*>/g,'');
      const tick=()=>{
        if(!this.speaking || this.speechText!==html) return;
        this.speechIndex++;
        const partial=plain.slice(0,this.speechIndex);
        this.bubble.textContent=partial+(this.speechIndex<plain.length?'▌':'');
        if(this.speechIndex<plain.length) setTimeout(tick,28+Math.random()*24);
        else this.bubble.innerHTML=html;
      };
      tick();
    }

    chooseIdle(){
      this.state='idle';
      this.timer=1.5+Math.random()*2.5;
      this.targetScale=.82;
    }

    chooseRoamTarget(){
      const pad=80;
      this.tx=pad+Math.random()*Math.max(1,innerWidth-pad*2);
      this.ty=pad+Math.random()*Math.max(1,innerHeight-pad*2);
      this.state='walk';
      this.timer=2.4+Math.random()*4.0;
      this.targetScale=.78+Math.random()*.08;
    }

    chooseRunTarget(){
      const pad=80;
      this.tx=pad+Math.random()*Math.max(1,innerWidth-pad*2);
      this.ty=pad+Math.random()*Math.max(1,innerHeight-pad*2);
      this.state='run';
      this.timer=1.8+Math.random()*2.5;
      this.targetScale=.82;
      this.say(this.data.name==='Adjiemas'?'running away!':'gotta go fast!', true);
    }

    chooseHideTarget(){
      const zones=getZones();
      if(!zones.length){ this.chooseRoamTarget(); return; }

      // Pilih elemen yang tidak terlalu kecil.
      const zone=zones[Math.floor(Math.random()*zones.length)];
      const r=zone.r;
      this.zone=zone;
      this.peekSide=Math.random()<.5?-1:1;

      // Berhenti di samping teks/card lalu sedikit "masuk" ke belakangnya.
      this.tx=clamp(
        this.peekSide<0 ? r.left-26 : r.right+26,
        28, innerWidth-28
      );
      this.ty=clamp(r.top+r.height*.5,60,innerHeight-55);
      this.state='hide';
      this.timer=1.3+Math.random()*2.0;
      this.targetScale=.50;
      this.say(Math.random()<.5?'👀':'shh...', true);
    }

    chooseChase(){
      this.state='chase';
      this.timer=3.2+Math.random()*2.8;
      this.targetScale=.82;
      this.say(this.data.name==='Adjiemas'?'hey wait!!':'hehe, got you!');
    }

    update(dt, all){
      this.timer-=dt;

      this.speechTimer-=dt;
      if(this.speechTimer<=0 && !this.speaking){
        const lines={
          Cabit:['yo!', 'h-hi im <b>Cabit</b>!', 'wait for me 😭', 'look at this!'],
          Ratono:['h-hi im <b>Ratono</b>!', 'where are you going?', 'hehe...', 'gotta run!'],
          Adjiemas:['h-hi im <b>Adjiemas</b>!', 'umm... hi 👋', 'don’t catch me!', 'look! a project!']
        };
        const pool=lines[this.data.name]||['h-hi im <b>'+this.data.name+'</b>!'];
        this.say(pool[Math.floor(Math.random()*pool.length)]);
      }
      if(this.speaking && this.speechTimer<=0){
        this.speaking=false;
        this.el.classList.remove('speaking');
        this.bubble.textContent='';
        this.speechTimer=2.5+Math.random()*4.5;
      }

      if(this.timer<=0){
        const roll=Math.random();
        if(this.state==='hide') this.chooseChase();
        else if(this.state==='chase') this.chooseHideTarget();
        else if(roll<.35) this.chooseChase();
        else if(roll<.55) this.chooseHideTarget();
        else if(roll<.72) this.chooseRunTarget();
        else if(roll<.85) this.chooseIdle();
        else this.chooseRoamTarget();
      }

      let target={x:this.tx,y:this.ty};

      if(this.state==='chase'){
        const prey=all[this.data.chase];
        target={x:prey.x,y:prey.y};
        // Jangan menempel terlalu dekat.
        const d=dist(this,prey);
        if(d<74){
          this.tx=this.x+(this.x-prey.x)*.4;
          this.ty=this.y+(this.y-prey.y)*.4;
        }
      }

      if(this.state==='hide' && this.zone){
        const r=this.zone.r;
        // Sedikit bergerak naik-turun seperti mengintip.
        target.x=clamp(
          this.peekSide<0 ? r.left+6 : r.right-6,
          25, innerWidth-25
        );
        target.y=clamp(r.top+r.height*.5+Math.sin(performance.now()/280+this.phase)*5,55,innerHeight-50);
      }

      const dx=target.x-this.x, dy=target.y-this.y;
      const d=Math.hypot(dx,dy)||1;

      let speed=this.data.speed;
      if(this.state==='hide') speed*=1.35;
      if(this.state==='chase') speed*=1.12;
      if(this.state==='run') speed*=1.5;
      if(this.state==='idle') speed*=0;

      // Smooth steering, bukan teleport.
      const desiredX=dx/d*speed;
      const desiredY=dy/d*speed;
      const steer=1-Math.pow(.001,dt);
      this.vx=lerp(this.vx,desiredX,steer);
      this.vy=lerp(this.vy,desiredY,steer);

      this.x+=this.vx*dt;
      this.y+=this.vy*dt;

      // Boundary bounce lembut.
      const pad=25;
      if(this.x<pad){this.x=pad;this.vx=Math.abs(this.vx)}
      if(this.x>innerWidth-pad){this.x=innerWidth-pad;this.vx=-Math.abs(this.vx)}
      if(this.y<pad+15){this.y=pad+15;this.vy=Math.abs(this.vy)}
      if(this.y>innerHeight-pad){this.y=innerHeight-pad;this.vy=-Math.abs(this.vy)}

      if(Math.abs(this.vx)>3) this.flip=this.vx<0?-1:1;
      this.walk+=Math.hypot(this.vx,this.vy)*dt*.055;

      const v=Math.hypot(this.vx,this.vy);
      const moving=v>18;
      const running=v>80;
      const bobAmount=running?3.2:moving?2.2:1;
      const bobSpeed=running?45:moving?60:380;
      const bob=moving ? Math.sin(this.walk)*bobAmount : Math.sin(performance.now()/bobSpeed+this.phase)*bobAmount;
      // Idle breathing: subtle scale pulse
      if(this.state==='idle'){
        const breath=Math.sin(performance.now()/600+this.phase)*0.015;
        this.targetScale=.82+breath;
      }
      this.scale=lerp(this.scale,this.targetScale,1-Math.pow(.0005,dt));

      // Saat hide: target berada di bawah elemen teks secara visual.
      const behind=this.state==='hide';
      this.alpha=lerp(this.alpha,behind?.58:1,1-Math.pow(.0008,dt));
      this.el.classList.toggle('peek',behind);

      const rot=clamp(this.vx*.018,-5,5);
      this.el.style.transform=
        `translate3d(${this.x-41}px,${this.y-100+bob}px,0) `+
        `scaleX(${this.flip*this.scale}) scaleY(${this.scale}) rotate(${rot}deg)`;
      this.el.style.opacity=this.alpha;

      // Z-index berubah saat "ngumpet".
      this.el.style.zIndex=behind?'4':'10000';
    }
  }

  async function start(){
    const sprites=[];
    for(let i=0;i<CHARACTERS.length;i++){
      sprites.push(await makeSprite(CHARACTERS[i],CROPS[i]));
    }

    const chars=CHARACTERS.map((d,i)=>new PixelChar(d,i,sprites[i]));
    chars.forEach(c=>c.chooseRoamTarget());

    // Mulai staggered supaya tidak terlihat seperti tiga objek spawn bersamaan.
    chars[0].timer=1.0;
    chars[1].timer=2.8;
    chars[2].timer=4.2;

    let last=performance.now();
    function frame(now){
      const dt=Math.min((now-last)/1000,.033);
      last=now;

      // Update DOM zone positions setiap frame secara murah.
      // Hanya saat ada karakter yang sedang hide.
      for(const c of chars) c.update(dt,chars);

      requestAnimationFrame(frame);
    }
    requestAnimationFrame(frame);

    // Resize menjaga posisi tetap di layar.
    addEventListener('resize',()=>{
      for(const c of chars){
        c.x=clamp(c.x,25,innerWidth-25);
        c.y=clamp(c.y,40,innerHeight-30);
      }
    },{passive:true});
  }

  start().catch(err=>console.error('Pixel characters:',err));
})();
